def closed_form_noP(H4, B):
    """SS3 closed form without P: H4<=2B -> eta=2H4,R=H4,W=0; else
    eta=H4+2B, R=2B, W=H4-2B (H4,B in Q22 volume units)."""
    if H4 <= 2 * B:
        return 2 * H4, H4, 0
    return H4 + 2 * B, 2 * B, H4 - 2 * B

